application.css:
:root {
  --ink: #182338;
  --muted: #68738a;
  --line: #e4e8f0;
  --accent: #635bdb;
  --accent-dark: #4d46bd;
  --soft: #f5f6ff;
  --success: #168268;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--ink);
  background: radial-gradient(circle at 10% 0%, #e9e9ff 0, transparent 33%), linear-gradient(135deg, #f8f9fc, #eef0f9);
}
.page-shell { width: min(920px, calc(100% - 32px)); margin: 0 auto; padding: 58px 0 28px; }
.quiz-card { background: rgba(255,255,255,.94); border: 1px solid rgba(255,255,255,.8); border-radius: 24px; box-shadow: 0 22px 60px rgba(40,48,91,.12); overflow: hidden; }
.quiz-header { padding: 42px 48px 32px; border-bottom: 1px solid var(--line); }
.eyebrow { color: var(--accent); font-size: 11px; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 10px 0 8px; font-size: clamp(30px, 5vw, 46px); letter-spacing: -.045em; }
.quiz-header p { color: var(--muted); margin: 0; font-size: 15px; }
.questions { padding: 10px 48px; }
.question { border: 0; border-bottom: 1px solid var(--line); padding: 25px 0 27px; margin: 0; min-width: 0; }
.question:last-child { border-bottom: 0; }
legend { width: 100%; padding: 0; display: flex; align-items: flex-start; gap: 16px; font-weight: 700; font-size: 17px; }
.question-number { color: var(--accent); font-size: 12px; letter-spacing: .1em; padding-top: 4px; }
.options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 11px; margin: 19px 0 0 43px; }
.option { display: flex; align-items: center; gap: 9px; border: 1px solid var(--line); border-radius: 11px; padding: 13px 14px; color: #4a556d; font-size: 14px; cursor: pointer; transition: .18s ease; }
.option:hover { border-color: #aaa6ed; background: var(--soft); transform: translateY(-1px); }
.option:has(input:checked) { border-color: var(--accent); color: var(--accent-dark); background: var(--soft); box-shadow: 0 0 0 2px rgba(99,91,219,.1); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-mark { width: 16px; height: 16px; flex: 0 0 16px; border: 1.5px solid #bdc4d2; border-radius: 50%; position: relative; }
.option input:checked + .radio-mark { border-color: var(--accent); }
.option input:checked + .radio-mark::after { content: ""; position: absolute; inset: 3px; background: var(--accent); border-radius: 50%; }
.quiz-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 27px 48px 30px; background: #fbfbfe; }
.submit-button { border: 0; border-radius: 10px; padding: 14px 20px; background: var(--accent); color: white; font-weight: 750; font-size: 14px; cursor: pointer; box-shadow: 0 8px 18px rgba(99,91,219,.25); }
.submit-button:hover { background: var(--accent-dark); transform: translateY(-1px); }
.submit-button span { font-size: 19px; margin-left: 8px; vertical-align: -1px; }
.result { display: flex; align-items: baseline; gap: 7px; }
.result-label { color: var(--muted); font-size: 13px; }
.result strong { color: var(--accent); font-size: 30px; line-height: 1; }
.out-of { color: var(--muted); font-size: 14px; }
.message { min-height: 22px; margin: -17px 48px 20px; color: #bd4c57; font-size: 13px; text-align: right; }
.page-footer { text-align: center; color: #8b93a8; font-size: 12px; padding-top: 20px; }
@media (max-width: 650px) { .page-shell { padding-top: 22px; } .quiz-header, .questions { padding-left: 24px; padding-right: 24px; } .options { grid-template-columns: 1fr; margin-left: 0; } .quiz-footer { padding: 24px; align-items: flex-start; flex-direction: column-reverse; } .message { margin-left: 24px; margin-right: 24px; text-align: left; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const message = document.getElementById('message');
const answers = { q1: 'mars', q2: 'pacific', q3: 'six' };

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const data = new FormData(form);
  const names = Object.keys(answers);
  const unanswered = names.filter((name) => !data.get(name));

  if (unanswered.length) {
    message.textContent = `Please answer ${unanswered.length === 1 ? 'the remaining question' : 'all questions'} before submitting.`;
    scoreElement.textContent = '—';
    scoreElement.removeAttribute('data-score');
    return;
  }

  let score = 0;
  names.forEach((name) => {
    if (data.get(name) === answers[name]) score += 1;
  });
  scoreElement.textContent = String(score);
  scoreElement.setAttribute('data-score', String(score));
  message.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Nice try! Review your answers and try again.';
});

form.addEventListener('change', () => {
  message.textContent = '';
});

